        return {}, text
    end = None
    for i in range(1, len(lines)):
        if lines[i].strip() == "---":
            end = i
            break
    if end is None:
        return {}, text
    meta: dict[str, Any] = {}
    for line in lines[1:end]:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if ":" in stripped:
            key, raw = stripped.split(":", 1)
            meta[key.strip()] = parse_simple_value(raw)
    body = "\n".join(lines[end + 1 :])
    if text.endswith("\n"):
