    )
    escaped = re.sub(r"`([^`]+)`", lambda m: stash(rf"\mdcode{{{escape_tex(m.group(1))}}}"), escaped)
    escaped = re.sub(r"\*\*([^*]+)\*\*", lambda m: stash(rf"\mdstrong{{{escape_tex(m.group(1))}}}"), escaped)
    escaped = re.sub(r"__([^_]+)__", lambda m: stash(rf"\mdstrong{{{escape_tex(m.group(1))}}}"), escaped)
    escaped = re.sub(r"(?<!\*)\*([^*]+)\*(?!\*)", lambda m: stash(rf"\emph{{{escape_tex(m.group(1))}}}"), escaped)
    escaped = re.sub(r"(?<!_)_([^_]+)_(?!_)", lambda m: stash(rf"\emph{{{escape_tex(m.group(1))}}}"), escaped)
    for key, value in placeholders.items():
        escaped = escaped.replace(key, value)
    return escaped


def block_visible_text(block: Block) -> str:
    if block.kind in {"heading", "paragraph", "blockquote"}:
        return strip_inline_markdown(block.text).replace("\n", "")
    if block.kind in {"ul", "ol"}:
        return "".join(strip_inline_markdown(item) for item in block.items)
    if block.kind == "code":
        return block.text.replace("\n", "")
    return ""


def block_word_count(block: Block) -> int:
    if block.kind == "heading":
        return 1
    if block.kind in {"ul", "ol"}:
        return 1 if block.items else 0
    text = block_visible_text(block)
    if not text.strip():
        return 0
    return len(re.findall(r"\S+", text))


def stats_text(book: BookDoc) -> str:
    rows: list[tuple[str, int, int]] = []
    total_chars = 0
    total_words = 0
    for chapter in book.chapters:
        chars = sum(len(block_visible_text(block)) for block in chapter.blocks)
        words = sum(block_word_count(block) for block in chapter.blocks)
        total_chars += chars
        total_words += words
        rows.append((chapter.source_path.name, chars, words))
    lines = ["Chapter      Chars      Words  Chars/Word", "---------"]
    for name, chars, words in rows:
        ratio = chars / words if words else 0.0
        lines.append(f"{name:<6}{chars:>12}{words:>11}{ratio:>12.2f}")
